(async () => {
  const c = tumblehorde.campaign;
  const log = [];
  const errors = [];
  window.addEventListener('error', (e) => errors.push(String(e.message)));
  const start = performance.now();
  let last = '';
  let pick = 0;
  document.getElementById('campaign-new').click();
  while (performance.now() - start < 170000) {
    const ph = c.phase.kind;
    const ch = c.save?.chapter;
    const key = `${ch}:${ph}`;
    if (key !== last) { log.push(key); last = key; }
    if (ph === 'idle') break;
    if (ph === 'loading') c.phase.timer = 0;
    if (ph === 'cutscene') c.player.update(1, true);
    if (ph === 'roam') c.finishChapter(ch);
    if (ph === 'battle') {
      const s = tumblehorde.session()?.match;
      if (s && s.phase === 'playing') {
        tumblehorde.unpause();
        const myTeam = s.armies[0].team;
        if (ch === 'last-night') { const me = s.units[s.armies[0].commanderId]; if (me.alive) { me.hp = 0; me.alive = false; s.armies[0].stats.commanderDeaths++; } }
        else for (const u of s.units) if (s.armies[u.armyId].team !== myTeam && u.alive) { u.alive = false; u.hp = 0; }
      }
      tumblehorde.fastForward(1);
    }
    const choice = document.querySelector('.cine-choices button');
    if (choice) { const all = document.querySelectorAll('.cine-choices button'); all[pick++ % all.length].click(); }
    if (ph === 'card') { const b = [...document.querySelectorAll('.overlay:not([hidden]) .btn.primary')].find((x) => x.offsetParent !== null); if (b) { log.push('card: ' + b.textContent); b.click(); } }
    await new Promise((r) => setTimeout(r, 30));
  }
  return JSON.stringify({ log, errors, save: c.save && { chapter: c.save.chapter, choices: c.save.choices, dead: c.save.legion.filter((l) => !l.alive).length } });
})()
